import json
import sqlite3
from datetime import datetime
from fractions import Fraction
from pathlib import Path

STEPS = ('install', 'tutorial_complete', 'first_match', 'purchase')
connection = sqlite3.connect('file:analytics.db?mode=ro', uri=True)
platforms = [row[0] for row in connection.execute('SELECT DISTINCT platform FROM users ORDER BY platform')]
funnel = {platform: dict.fromkeys(STEPS, 0) for platform in platforms}
player_events = {}
for player, platform, name, timestamp in connection.execute('SELECT u.user_id,u.platform,e.name,e.ts FROM users u JOIN events e ON e.user_id=u.user_id WHERE u.is_test=0'):
    if name in STEPS:
        player_events.setdefault((player, platform), {}).setdefault(name, []).append(datetime.fromisoformat(timestamp))
for (_, platform), occurrences in player_events.items():
    previous = None
    for step in STEPS:
        valid = [timestamp for timestamp in occurrences.get(step, []) if previous is None or timestamp >= previous]
        if not valid:
            break
        previous = min(valid)
        funnel[platform][step] += 1
biggest_drop = {}
for platform, counts in funnel.items():
    candidates = [(Fraction(counts[step], counts[STEPS[index - 1]]), index, step) for index, step in enumerate(STEPS) if index and counts[STEPS[index - 1]]]
    biggest_drop[platform] = min(candidates)[2] if candidates else None
result = {'funnel': funnel, 'biggest_drop': biggest_drop}
Path('result.json').write_text(json.dumps(result, indent=2) + '\n', encoding='utf-8')
print(Path('result.json').read_text(encoding='utf-8'))

# Independent SQL reconstruction validates the chronological Python calculation.
query = '''
WITH installs AS (
 SELECT u.user_id,u.platform,MIN(e.ts) AS ts
 FROM users u JOIN events e ON e.user_id=u.user_id
 WHERE u.is_test=0 AND e.name='install' GROUP BY u.user_id,u.platform
), tutorials AS (
 SELECT i.user_id,i.platform,MIN(e.ts) AS ts FROM installs i
 JOIN events e ON e.user_id=i.user_id AND e.name='tutorial_complete' AND e.ts>=i.ts
 GROUP BY i.user_id,i.platform
), matches AS (
 SELECT t.user_id,t.platform,MIN(e.ts) AS ts FROM tutorials t
 JOIN events e ON e.user_id=t.user_id AND e.name='first_match' AND e.ts>=t.ts
 GROUP BY t.user_id,t.platform
), purchases AS (
 SELECT m.user_id,m.platform,MIN(e.ts) AS ts FROM matches m
 JOIN events e ON e.user_id=m.user_id AND e.name='purchase' AND e.ts>=m.ts
 GROUP BY m.user_id,m.platform
)
SELECT platform,'install',COUNT(*) FROM installs GROUP BY platform
UNION ALL SELECT platform,'tutorial_complete',COUNT(*) FROM tutorials GROUP BY platform
UNION ALL SELECT platform,'first_match',COUNT(*) FROM matches GROUP BY platform
UNION ALL SELECT platform,'purchase',COUNT(*) FROM purchases GROUP BY platform
'''
for (timestamp,) in connection.execute('SELECT ts FROM events'):
    assert datetime.fromisoformat(timestamp).strftime('%Y-%m-%d %H:%M:%S') == timestamp, 'SQL ordering requires canonical timestamps'
sql_funnel = {platform: dict.fromkeys(STEPS, 0) for platform in platforms}
for platform, step, count in connection.execute(query):
    sql_funnel[platform][step] = count
assert sql_funnel == funnel, 'Independent SQL and Python funnel counts differ'
assert json.loads(Path('result.json').read_text(encoding='utf-8')) == result
print('PASS: independent SQL and Python agree on every platform and step; result.json round-trip matches.')
for platform, counts in funnel.items():
    for index, step in enumerate(STEPS[1:], 1):
        denominator = counts[STEPS[index - 1]]
        print(f'{platform} {step}: {counts[step]}/{denominator}; lost={denominator-counts[step]}; conversion={counts[step]/denominator:.6%}' if denominator else f'{platform} {step}: undefined conversion')


